head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDFIS00600_P7.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_Top);

    // 데이터셋 초기화
    scwin.fn_InitDs();
    scwin.fn_Search();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {

};

/**
 *  데이터셋 clear.
 */
scwin.fn_ClearDs = function() {
    dts_Fz530.removeAll();
    dts_Fz531.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    return true;
};


/**
 * 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_ClearDs();

    // 조회조건 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_FZ530);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.conditionMaster" + "&outputMessageId=FIS_COND_MASTR_INFO" + "&param01=" + js_emp_no;
    dts_Fz530.DataID = encodeURI(url);
    dts_Fz530.Reset();
};


/**
 * 디테일 조회
 */
scwin.fn_SearchDetail = function(row) {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.conditionDetail" + "&outputMessageId=FIS_COND_DETL_LIST" + "&param01=" + dts_Fz530.getCellData(row, "EMP_NO") + "&param02=" + dts_Fz530.getCellData(row, "TYP") + "&param03=" + dts_Fz530.getCellData(row, "GUBUN") + "&param04=" + dts_Fz530.getCellData(row, "SEQ_NO");
    dts_Fz531.DataID = encodeURI(url);
    dts_Fz531.Reset();
};


/**
 * 삭제
 */
scwin.fn_Delete = function() {
    if (!confirm("삭제하시겠습니까?")) {
        return;
    }
    //dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "EMP_NO", dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "EMP_NO"));
    dts_Delete.setCellData(1, "TYP", dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "TYP"));
    dts_Delete.setCellData(1, "GUBUN", dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "GUBUN"));
    dts_Delete.setCellData(1, "SEQ_NO", dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "SEQ_NO"));
    trs_Delete.Action = "/ConditionSrchAction.do?method=removeCondition" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_Delete.KeyName = "toinb_dataid4";
    trs_Delete.KeyValue = "JSP(I:pInput=dts_Delete)";
    trs_Delete.Post();
};


/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.fn_SetParam = function() {
    var pCondition = dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "CONTENT");
    // 조회조건을 화면에 세팅.		
    var aCond = pCondition.split("|");
    var aCondPair;
    for (var i = 0; i < aCond.length; i++) {
        aCondPair = $c.stf.trim(aCond[i]).split("=");
        if (aCondPair[0] == "cmb_IND_PTTN") {
            $c.stf.setObjectValue(opener.cmb_IND_PTTN, aCondPair[1]);
        }
    }
    opener.fn_setCondTitle("조건명 : " + dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "COND_NM"));
    opener.fn_setCondNm(dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "COND_NM"));
    opener.fn_setCondCon(dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "COND_CON"));
    opener.fn_SetCondition(dts_Fz531, dts_Fz530.getCellData(dts_Fz530.getRowPosition(), "CONTENT"));
};
scwin.dts_Fz530_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_FZ530);
    $c.stf.alert_error(dts_Fz530);
};
scwin.dts_Fz531_OnLoadError = function() {
    //CloseWin(-1, grd_FZ530);
    $c.stf.alert_error(dts_Fz531);
};
scwin.dts_Fz530_OnLoadCompleted = function(rowcount) {
    if (dts_Fz530.errorMsg) {
        $c.win.alert(dts_Fz530.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_FZ530);
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.img_Close_onclick = async function() {
    // 닫기버튼 클릭
    await $c.frame.CloseFrame();
};
scwin.image_1_onclick = function() {
    if (dts_Fz530.getRowPosition() < 1) {
        return;
    }
    scwin.fn_Delete();
};
scwin.trs_Delete_OnSuccess = function() {
    //alert( getMessageParam("MSG-A001", "삭제") );
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    // 재조회
    scwin.fn_Search();
    opener.fn_Reset();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert(trs_Delete.ErrorMsg);
};
scwin.dts_Fz531_OnLoadCompleted = function(rowcount) {
    scwin.fn_SetParam();
};
scwin.grd_FZ530_OnClick = function(row, colid) {
    // 디테일 FZ531 조회
    scwin.fn_SearchDetail(row);
};
